HANDLE hntMapping = CreateFileMappingA(hntFile, NULL, PAGE_READONLY| SEC_IMAGE,0,0,NULL);
LPVOID DiskNtdllBase = MapViewOfFile(hntMapping, FILE_MAP_READ, 0, 0, 0);
