		memcpy((LPVOID)((BYTE*)memNtdllBase + memSectionHeader->VirtualAddress), (LPVOID)((BYTE*)DiskNtdllBase + memSectionHeader->VirtualAddress), memSectionHeader->Misc.VirtualSize);
