using namespace std;

// 定义内存页属性结构体
struct MemoryAttrib {
    LPVOID address;		// 内存地址
    DWORD size;			// 内存大小
};

// 定义内存信息结构体
struct MemoryInfo {
    MemoryAttrib memoryPage[3];		// 能找到符合条件的目标内存最多3个
    int index = 0;					// 内存下标
    BOOL iscleaned = FALSE;			//是否清除之前的beacon和shellcode遗留
